-- ASHE International: D1 (SQLite) schema ported from the MySQL schema + v2 migrations of the PHP API.
-- Money columns are REAL for parity with the old DECIMAL columns; move to integer minor units before heavy finance reporting.
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, is_active INTEGER NOT NULL DEFAULT 1, reset_token TEXT, reset_expires TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_users_reset_token ON users(reset_token);
CREATE TABLE IF NOT EXISTS profiles (id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, display_name TEXT, organization TEXT, phone TEXT, avatar_url TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_roles (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK (role IN ('admin','designer','finance','partner','donor','fundraiser')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (user_id, role));
CREATE TABLE IF NOT EXISTS organizations (id TEXT PRIMARY KEY, owner_id TEXT REFERENCES users(id) ON DELETE SET NULL, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, org_type TEXT NOT NULL DEFAULT 'ngo', description TEXT, website TEXT, country TEXT, logo_url TEXT, is_donor INTEGER NOT NULL DEFAULT 0, min_pledge_usd REAL, accepted_terms INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, owner_id TEXT REFERENCES users(id) ON DELETE SET NULL, title TEXT NOT NULL, slug TEXT UNIQUE, category TEXT NOT NULL, location TEXT, story TEXT, image_url TEXT, goal_amount REAL NOT NULL DEFAULT 0, raised_amount REAL NOT NULL DEFAULT 0, donor_count INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('draft','pending','active','funded','closed')), is_promoted INTEGER NOT NULL DEFAULT 0, is_staff_pick INTEGER NOT NULL DEFAULT 0, is_loved INTEGER NOT NULL DEFAULT 0, is_suspended INTEGER NOT NULL DEFAULT 0, signed_consent_url TEXT, consent_signed_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_projects_status ON projects(status);
CREATE INDEX IF NOT EXISTS idx_projects_owner ON projects(owner_id);
CREATE TABLE IF NOT EXISTS donations (id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id) ON DELETE SET NULL, donor_user_id TEXT REFERENCES users(id) ON DELETE SET NULL, donor_name TEXT, donor_email TEXT, amount REAL NOT NULL, currency TEXT NOT NULL DEFAULT 'USD', message TEXT, is_anonymous INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','completed','failed','refunded')), payment_provider TEXT, payment_reference TEXT, tracking_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_donations_project ON donations(project_id);
CREATE INDEX IF NOT EXISTS idx_donations_donor ON donations(donor_user_id);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, type TEXT NOT NULL, title TEXT NOT NULL, body TEXT, metadata TEXT, is_read INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS homepage_content (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS withdrawal_requests (id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id) ON DELETE SET NULL, requester_id TEXT REFERENCES users(id) ON DELETE SET NULL, amount REAL NOT NULL, method TEXT NOT NULL DEFAULT 'bank', details TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','paid')), reviewed_by TEXT, reviewed_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, value TEXT, description TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS bug_reports (id TEXT PRIMARY KEY, reporter_id TEXT REFERENCES users(id) ON DELETE SET NULL, title TEXT NOT NULL, description TEXT, url TEXT, severity TEXT NOT NULL DEFAULT 'medium' CHECK (severity IN ('low','medium','high','critical')), status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','in_progress','resolved','wont_fix')), admin_notes TEXT, is_resolved INTEGER NOT NULL DEFAULT 0, resolved_by TEXT, resolved_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS project_milestones (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, position INTEGER NOT NULL DEFAULT 1, title TEXT NOT NULL, description TEXT, amount REAL NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','active','completed')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_pm_project ON project_milestones(project_id);
CREATE TABLE IF NOT EXISTS project_sponsors (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, amount REAL NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_ps_project ON project_sponsors(project_id);
CREATE INDEX IF NOT EXISTS idx_ps_org ON project_sponsors(organization_id);
CREATE TABLE IF NOT EXISTS project_payouts (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, method TEXT NOT NULL DEFAULT 'bank', country TEXT, network_provider TEXT, phone TEXT, swift_code TEXT, bank_name TEXT, account_holder TEXT, account_number TEXT, proxy_video_url TEXT, proxy_agreement_url TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_pp_project ON project_payouts(project_id);
CREATE TABLE IF NOT EXISTS proxy_receivers (id TEXT PRIMARY KEY, payout_id TEXT NOT NULL REFERENCES project_payouts(id) ON DELETE CASCADE, full_name TEXT NOT NULL, id_document_url TEXT, position INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_pr_payout ON proxy_receivers(payout_id);
